import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import 'private_chat.dart';
import 'country_flag.dart';
import 'rank_frame.dart';

class PrivateConversationsPage extends StatelessWidget{const PrivateConversationsPage({super.key});
 @override Widget build(BuildContext context)=>Scaffold(backgroundColor:const Color(0xFF090604),appBar:AppBar(backgroundColor:const Color(0xFF100805),foregroundColor:Colors.white,title:const Text('المحادثات 💬',style:TextStyle(color:Color(0xFFFFD36A),fontWeight:FontWeight.w900))),body:FutureBuilder<List<dynamic>>(future:Supabase.instance.client.rpc('private_conversations'),builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text('خطأ: ${s.error}',style:const TextStyle(color:Colors.white)));final rows=(s.data??[]);if(rows.isEmpty)return const Center(child:Text('لا توجد محادثات بعد',style:TextStyle(color:Colors.white54)));return ListView.builder(itemCount:rows.length,itemBuilder:(c,i){final x=Map<String,dynamic>.from(rows[i]);final unread=(x['unread_count'] as num?)?.toInt()??0;final fid=x['friend_id'].toString();return FutureBuilder<Map<String,dynamic>>(future:Supabase.instance.client.from('profiles').select('username,role,country_code,vip_level').eq('id',fid).maybeSingle().then((v)=>Map<String,dynamic>.from(v??{})),builder:(ctx,p){final prof=p.data??{};final name=prof['username']?.toString()??fid;final role=prof['role']?.toString()??'USER';final vip=prof['vip_level']?.toString();final country=prof['country_code']?.toString();return ListTile(leading:RankFrame(role:role,vipLevel:vip,size:42,showLabel:false,child:const CircleAvatar(backgroundColor:Color(0xFF120A06),child:Icon(Icons.person,color:Color(0xFFFFD36A),size:22))),title:Row(children:[CountryFlag(code:country,size:18),const SizedBox(width:6),Expanded(child:Text(name,style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w800))),if(vip!=null&&vip.isNotEmpty)Text(vip,style:const TextStyle(color:Color(0xFFFFD36A),fontSize:10,fontWeight:FontWeight.bold))]),subtitle:Text(x['last_message']??'',maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(color:Colors.white54)),trailing:unread>0?CircleAvatar(radius:13,backgroundColor:const Color(0xFFFFC107),child:Text('$unread',style:const TextStyle(color:Colors.black,fontWeight:FontWeight.bold))):null,onTap:(){Supabase.instance.client.rpc('mark_private_messages_read',params:{'p_friend':fid});Navigator.push(context,MaterialPageRoute(builder:(_)=>PrivateChatPage(friendId:fid)));});});});});
}